<?php
require_once __DIR__.'/../backend/rutas_aprendizaje.php';
$slug=trim($_GET['slug']??'');$stmt=$conn->prepare("SELECT * FROM rutas_aprendizaje WHERE slug=? AND estado='publicada' LIMIT 1");$stmt->bind_param('s',$slug);$stmt->execute();$ruta=$stmt->get_result()->fetch_assoc();$stmt->close();
if(!$ruta){echo '<div class="container" style="margin-top:143px"><p>Ruta no encontrada.</p></div>';return;}
$items=ruta_items($conn,(int)$ruta['id']);$u=current_user();$hechas=0;$actual=null;
if($u){foreach($items as &$it){$it['completado']=ruta_item_completado($conn,(int)$u['id'],$it);if($it['completado'])$hechas++;elseif(!$actual)$actual=$it;}unset($it);if(($_GET['iniciar']??'')==='1')ruta_marcar_activa($conn,(int)$u['id'],(int)$ruta['id'],$actual['id']??null);}
$obligatorios=count(array_filter($items,fn($i)=>(int)$i['obligatorio']===1));$completosOblig=count(array_filter($items,fn($i)=>(int)$i['obligatorio']===1&&!empty($i['completado'])));$pct=$obligatorios?(int)round($completosOblig/$obligatorios*100):0;
?>
<section class="pf-section" style="margin-top:80px"><div class="pf-container"><div class="row align-items-center g-4 mb-5"><div class="col-lg-7"><span class="pf-eyebrow">Ruta de aprendizaje</span><h1 class="display-5 fw-bold"><?=htmlspecialchars($ruta['titulo'])?></h1><p class="fs-5 text-muted"><?=nl2br(htmlspecialchars($ruta['descripcion']))?></p><div class="d-flex gap-2 flex-wrap"><span class="badge bg-light text-dark"><?=htmlspecialchars(ucfirst($ruta['nivel']))?></span><?php if($ruta['duracion_min_estimada']):?><span class="badge bg-light text-dark">⏱ <?=round($ruta['duracion_min_estimada']/60,1)?> h estimadas</span><?php endif;?><?php if($ruta['responsable']):?><span class="badge bg-light text-dark">Guía: <?=htmlspecialchars($ruta['responsable'])?></span><?php endif;?></div></div><div class="col-lg-5"><?php if($ruta['imagen_portada']):?><img class="img-fluid rounded-4 shadow" src="<?=htmlspecialchars($ruta['imagen_portada'])?>" alt=""><?php endif;?></div></div>
<?php if($u):?><div class="card border-0 shadow-sm p-4 mb-4"><div class="d-flex justify-content-between"><strong>Tu avance</strong><span><?=$pct?>%</span></div><div class="progress my-2"><div class="progress-bar" style="width:<?=$pct?>%;background:#f7931e"></div></div><?php if($actual):?><a class="btn align-self-start mt-2" style="background:#f7931e;color:#fff" href="?action=<?=$actual['tipo_contenido']?>&slug=<?=urlencode($actual['slug'])?>&ruta=<?=urlencode($ruta['slug'])?>">Continuar ruta →</a><?php endif;?></div><?php else:?><div class="alert alert-light border mb-4">Crea tu Cuenta Arjuna para guardar el avance de esta ruta. <a href="?action=registro&volver=<?=urlencode($_SERVER['REQUEST_URI'])?>">Crear cuenta</a></div><?php endif;?>
<div class="d-grid gap-3"><?php foreach($items as $i=>$it):$href='?action='.$it['tipo_contenido'].'&slug='.urlencode($it['slug']).'&ruta='.urlencode($ruta['slug']);?><a href="<?=$href?>" class="card border-0 shadow-sm text-decoration-none text-body p-4"><div class="d-flex gap-3 align-items-start"><span class="rounded-circle d-grid text-center flex-shrink-0" style="width:42px;height:42px;line-height:42px;background:<?=!empty($it['completado'])?'#e6f4ea':'#fff3e0'?>"><?=!empty($it['completado'])?'✓':$i+1?></span><div><span class="small text-uppercase text-muted"><?=htmlspecialchars($it['tipo_contenido'])?><?=$it['obligatorio']?'':' · opcional'?></span><h2 class="h5 mb-1"><?=htmlspecialchars($it['titulo'])?></h2><?php if($it['introduccion']):?><p class="text-muted mb-0"><?=htmlspecialchars($it['introduccion'])?></p><?php endif;?></div></div></a><?php endforeach;?></div></div></section>
